-- Grameen Bazar cloud backend for Supabase
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade,name text not null,village text not null,role text not null default 'seller' check(role in ('seller','admin')),created_at timestamptz not null default now());
create table if not exists public.products (id text primary key,owner_id uuid not null references public.profiles(id) on delete cascade,name text not null,price numeric not null check(price>0),quantity integer not null default 0 check(quantity>=0),emoji text,images text[] not null default '{}',category text not null,artisan text not null,village text not null,description text default '',materials text default '',created_at timestamptz not null default now());
create table if not exists public.inventory (product_id text primary key,quantity integer not null default 0 check(quantity>=0));
create table if not exists public.orders (id text primary key,buyer_id uuid references auth.users(id) on delete set null,customer text not null,phone text not null,address text not null,total numeric not null,items jsonb not null,created_at timestamptz not null default now());
insert into public.inventory(product_id,quantity) values('P001',18),('P002',12),('P003',25),('P004',30),('P005',16),('P006',10) on conflict(product_id) do nothing;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,name,village,role) values(new.id,coalesce(new.raw_user_meta_data->>'name',split_part(new.email,'@',1)),coalesce(new.raw_user_meta_data->>'village','Village'),case when lower(new.email)='admin@grameenbazar.in' then 'admin' else 'seller' end) on conflict(id) do update set name=excluded.name,village=excluded.village; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
create or replace function public.decrement_product_stock(p_id text,p_qty integer) returns boolean language plpgsql security definer set search_path=public as $$ declare updated integer; begin update public.products set quantity=quantity-p_qty where id=p_id and quantity>=p_qty; get diagnostics updated=row_count; return updated=1; end; $$;
create or replace function public.decrement_inventory(p_id text,p_qty integer) returns boolean language plpgsql security definer set search_path=public as $$ declare updated integer; begin update public.inventory set quantity=quantity-p_qty where product_id=p_id and quantity>=p_qty; get diagnostics updated=row_count; return updated=1; end; $$;
alter table public.profiles enable row level security; alter table public.products enable row level security; alter table public.inventory enable row level security; alter table public.orders enable row level security;
drop policy if exists profiles_select on public.profiles; create policy profiles_select on public.profiles for select using(id=auth.uid() or public.is_admin());
drop policy if exists profiles_update on public.profiles; create policy profiles_update on public.profiles for update using(id=auth.uid() or public.is_admin());
drop policy if exists products_read on public.products; create policy products_read on public.products for select using(true);
drop policy if exists products_insert on public.products; create policy products_insert on public.products for insert with check(owner_id=auth.uid());
drop policy if exists products_update on public.products; create policy products_update on public.products for update using(owner_id=auth.uid() or public.is_admin()) with check(owner_id=auth.uid() or public.is_admin());
drop policy if exists products_delete on public.products; create policy products_delete on public.products for delete using(owner_id=auth.uid() or public.is_admin());
drop policy if exists inventory_read on public.inventory; create policy inventory_read on public.inventory for select using(true);
drop policy if exists orders_insert on public.orders; create policy orders_insert on public.orders for insert with check(buyer_id is null or buyer_id=auth.uid());
drop policy if exists orders_read on public.orders; create policy orders_read on public.orders for select using(buyer_id=auth.uid() or public.is_admin() or exists(select 1 from jsonb_array_elements(items) i where (i->>'ownerId')=auth.uid()::text));
grant execute on function public.decrement_product_stock(text,integer) to anon,authenticated; grant execute on function public.decrement_inventory(text,integer) to anon,authenticated;
